mapper.select:

WHERE c.tenant_id = #{tenant}
AND c.outbound_id = #{filter.outboundId}
AND c.carton_code = #{filter.cartonCode}

    AND EXISTS (SELECT 1 FROM wms_sales_package_pick pp
        JOIN wms_actual_pick k ON k.tenant_id = pp.tenant_id AND k.request_id = pp.pick_id
        JOIN wms_outbound_allocation a ON a.tenant_id = k.tenant_id AND a.allocation_id = k.allocation_id
        JOIN wms_inbound_order_line l ON l.tenant_id = a.tenant_id AND l.batch_no = a.batch_no
        JOIN wms_inbound_order r ON r.tenant_id = l.tenant_id AND r.order_id = l.order_id
        WHERE pp.tenant_id = c.tenant_id AND pp.package_id = c.carton_id
        AND a.batch_no = #{filter.batchNo}
        AND r.reference_id = #{filter.purchaseOrderId})

ORDER BY c.created_at, c.carton_id
